INSERT INTO city_chunks VALUES(48,'dc',0,'# City: Washington, DC # Scope: Homelessness context and resources # Timeframe: Data primarily from 2020–2024 ## Summary (High-level) - In 2024, DC counted 5,616 people experiencing homelessness: 3,960 unaccompanied individuals and 1,656 people in 539 family households. - 84% were in shelter or transitional housing, but unsheltered numbers and inflow, especially families, have risen since 2023. - Unaccompanied adults have high rates of disabling conditions and chronic homelessness; families are more connected to income but still face major housing barriers. --- ## Overall statistics and trends ### Population level and trends - FACT: Overall homeless population - City: Washington, DC - Topic: population_trend - Content: In 2024, DC counted 5,616 people: 3,960 unaccompanied individuals and 1,656 people in 539 families. This is up 14.1% (694 people) from 2023 but 12% below 2020. - FACT: Family vs unaccompanied trends - City: Washington, DC - Topic: population_trend_household_type - Content: From 2023–2024, unaccompanied individuals increased 5.6%, while people in families increased 41.3%. Since 2020, unaccompanied counts are nearly flat, but people in families are down 31.9%.','[0.0257720947265625,-0.03460693359375,0.032318115234375,-0.00267791748046875,0.061798095703125,0.030914306640625,0.06646728515625,0.06292724609375,-0.05059814453125,-0.05145263671875,-0.05560302734375,-0.04241943359375,-0.07745361328125,0.0303497314453125,-0.00604248046875,0.0286865234375,0.0784912109375,-0.01165771484375,0.028076171875,-0.000423431396484375,0.01483917236328125,-0.02081298828125,0.0141143798828125,0.0276947021484375,0.041717529296875,-0.02630615234375,0.035247802734375,-0.038238525390625,-0.09295654296875,-0.0206146240234375,0.01207733154296875,-0.0156707763671875,-0.0199432373046875,-0.02789306640625,0.04345703125,-0.007160186767578125,-0.0227813720703125,-0.01580810546875,0.0159912109375,0.0076446533203125,-0.01507568359375,-0.04641723