INSERT INTO city_chunks VALUES(78,'portland',0,'# City: Portland, Oregon (Multnomah County) # Scope: Homelessness context, policies, and resources # Timeframe: Data primarily from 2021–2025 ## SUMMARY: Overall homelessness situation in Portland - PATTERN: Rapid growth in homelessness - Content: Between January 2024 and January 2025, the estimated number of people experiencing homelessness in Multnomah County grew significantly, reaching around 14,400 people. - PATTERN: Shelters often near capacity - Content: Most nights, shelter beds in Multnomah County are close to full, with a high percentage of beds occupied. - PATTERN: More people entering than exiting homelessness - Content: Over recent years, more people have been entering homelessness than exiting into permanent housing, which causes the overall number of unhoused residents to keep rising. - PATTERN: Heavy reliance on public funding for housing - Content: City and county tax dollars support thousands of people who were previously homeless or at high risk of homelessness, including through subsidized housing and prevention programs.','[-0.004726409912109375,-0.0379638671875,0.0164794921875,-0.0151519775390625,0.08709716796875,0.047576904296875,0.060028076171875,0.038909912109375,-0.04742431640625,-0.06451416015625,-0.04632568359375,-0.03460693359375,-0.0894775390625,0.01071929931640625,0.0007753372192382812,0.042694091796875,0.0751953125,-0.0253753662109375,0.01568603515625,-0.0201873779296875,0.01763916015625,-0.0031147003173828125,0.005283355712890625,0.0262298583984375,0.05474853515625,-0.0223846435546875,0.03448486328125,0.002201080322265625,-0.0848388671875,0.0031566619873046875,0.0200958251953125,0.0013074874877929688,0.006328582763671875,-0.052947998046875,0.04248046875,0.01078033447265625,0.0081787109375,0.0046844482421875,-0.0029087066650390625,0.016632080078125,-0.0207366943359375,-0.032958984375,-0.04119873046875,-0.0266265869140625,-0.00665283203125,-0.034515380859375,0.021575927734375,0.0180511474