INSERT INTO city_chunks VALUES(84,'portland',6,'er Services - Type: resource_team - Population: people moving from unsheltered life toward stability - Content: City Shelter Services manages alternative shelters, overnight shelters, and day centers. The team provides access to case management, mental and behavioral health support, and connections to housing resources. ### RESOURCE GROUP: Street Services Coordination Center (SSCC) - Type: street_outreach - Population: unsheltered individuals - Content: The SSCC coordinates outreach to people living outside, offering shelter referrals, transportation, and other resources. ### RESOURCE GROUP: Impact Reduction Program - Type: impact_reduction - Population: unsheltered people and surrounding communities - Content: This program focuses on reducing the immediate impacts of unsheltered homelessness through trash removal, hygiene access, resource referrals, job opportunities, and the removal of campsites that pose high health and safety risks. ### RESOURCE GROUP: Public Environment Management Office (PEMO) - Type: public_space_management - Content: PEMO coordinates city resources to respond quickly to livability issues in public spaces, such as encampments and environmental damage. ## POLICY: Camping restrictions - Type: camping_policy - Content: Portland’s camping rules restrict where and how people can camp.','[0.032562255859375,-0.01161956787109375,-0.0269775390625,0.0183258056640625,0.06884765625,0.053253173828125,0.03143310546875,0.04608154296875,-0.0195770263671875,-0.0740966796875,-0.049591064453125,-0.01215362548828125,-0.07391357421875,0.0089874267578125,0.031341552734375,0.03399658203125,0.0772705078125,-0.0080413818359375,-0.01287078857421875,0.026275634765625,0.034088134765625,-0.0041046142578125,-0.0044403076171875,0.01560211181640625,0.0030841827392578125,0.02435302734375,0.03228759765625,-0.00811004638671875,-0.04595947265625,-0.007537841796875,0.0341796875,0.03143310546875,-0.026153564453125,-0.013717651367187