INSERT INTO city_chunks VALUES(85,'portland',7,'ssues in public spaces, such as encampments and environmental damage. ## POLICY: Camping restrictions - Type: camping_policy - Content: Portland’s camping rules restrict where and how people can camp. People are prohibited from blocking sidewalks or private property, building structures, using fires or gas heaters at camps, damaging infrastructure or the environment, or storing belongings far outside their tents. Some areas are explicitly marked “no trespassing.” - IMPACT: These rules can push unsheltered people to move frequently and may increase interactions with law enforcement or city crews, which can disrupt people’s ability to keep belongings, documents, or stability.','[0.0165863037109375,0.007808685302734375,-0.01412200927734375,-0.0130615234375,0.059326171875,-0.021881103515625,0.05853271484375,0.0128173828125,-0.051483154296875,-0.056610107421875,-0.043365478515625,-0.0662841796875,-0.0660400390625,0.0570068359375,-0.004650115966796875,0.0631103515625,0.022918701171875,-0.0187225341796875,-0.046051025390625,-0.00981903076171875,0.0887451171875,-0.0228118896484375,0.0026111602783203125,0.0133056640625,0.0311279296875,0.03656005859375,0.0533447265625,0.0212554931640625,-0.039154052734375,0.005615234375,0.0123443603515625,0.0233306884765625,-0.02001953125,-0.024627685546875,0.0283660888671875,-0.0190887451171875,-0.00247955322265625,-0.0108184814453125,-0.032440185546875,0.017425537109375,-0.0220947265625,-0.0151519775390625,-0.03472900390625,-0.0268707275390625,-0.0263671875,0.021514892578125,0.039154052734375,-0.01430511474609375,-0.0521240234375,-0.07861328125,-0.07275390625,0.0406494140625,0.0254058837890625,0.0186004638671875,0.0242919921875,0.0148773193359375,-0.049163818359375,-0.06170654296875,0.009429931640625,-0.06268310546875,0.0222015380859375,0.032196044921875,0.018096923828125,-0.00897216796875,0.00745391845703125,-0.01541900634765625,-0.0270843505859375,0.031707763671875,0.0000661611557006836,-0.0