INSERT INTO city_chunks VALUES(86,'portland',8,'e rules can push unsheltered people to move frequently and may increase interactions with law enforcement or city crews, which can disrupt people’s ability to keep belongings, documents, or stability. # CITY-SPECIFIC RESOURCES (PORTLAND) ## RESOURCE TYPE: Alternative shelters and village-style pods ### RESOURCE: Clinton Triangle (1490 SE Gideon St.) - Type: alternative_shelter_village - Population: adults 18+ (referral only) - Access: referrals from outreach workers; no waitlist - Features: - Tiny home units arranged in small clusters - Pets allowed; couples can stay together; no outside guests - No set time limit on stay, though intended as transitional housing - ADA-accessible restrooms and showers - At least one meal per day, laundry, storage, electricity, Wi‑Fi - Nearby public transit - Case management and service planning to identify barriers to housing and connect guests with medical and other resources - NOTE: Designed to offer more stability and privacy than large congregate shelters.','[0.0090179443359375,-0.042694091796875,-0.005764007568359375,0.0118560791015625,0.0809326171875,0.021087646484375,0.02069091796875,0.0247650146484375,-0.0443115234375,-0.074951171875,-0.0302581787109375,-0.05108642578125,-0.090576171875,0.02001953125,0.0235443115234375,0.041107177734375,0.05706787109375,-0.0287933349609375,-0.0143585205078125,-0.0264434814453125,0.0269775390625,-0.0121612548828125,0.0081634521484375,0.01059722900390625,0.0182037353515625,0.01141357421875,0.0266265869140625,-0.01262664794921875,-0.0292205810546875,-0.0053558349609375,0.015350341796875,0.0252227783203125,0.007598876953125,-0.00409698486328125,0.0265350341796875,-0.01123809814453125,-0.0244140625,-0.0223846435546875,-0.01702880859375,-0.00634765625,-0.00222015380859375,-0.010284423828125,-0.002719879150390625,-0.0029659271240234375,-0.0014696121215820312,0.0172882080078125,0.00922393798828125,0.007114410400390625,-0.08734130859375,-0.08221435546875