INSERT INTO city_chunks VALUES(87,'portland',9,'management and service planning to identify barriers to housing and connect guests with medical and other resources - NOTE: Designed to offer more stability and privacy than large congregate shelters. ### RESOURCE: Menlo Park Safe Rest Village (12305 SE Ash St.) - Type: alternative_shelter_village - Population: adults 18+ (referral only) - Access: referrals from outreach workers; no waitlist - Features: - Tiny homes organized in pods - Pets allowed; couples can stay together; no outside guests - Intended as transitional; no formal time limit - Day services to connect people with healthcare, mental health support, employment support, and other resources ### RESOURCE: Naito Village - Type: alternative_shelter_village - Population: LGBTQIA2S+ adults - Access: referral-based - Features: - Community built around queer and trans residents, emphasizing safety and mutual support - Tiny home units with wrap-around services (meals, hygiene, laundry, storage, Wi‑Fi, transit access) - Service planning to identify barriers to housing and connect residents to medical and social resources - NOTE: Provides an affirming environment for LGBTQIA2S+ people who may not feel safe or welcome in other shelters.','[-0.018280029296875,-0.032318115234375,0.01418304443359375,-0.0015344619750976562,0.0653076171875,0.034454345703125,0.055877685546875,-0.01318359375,-0.04052734375,-0.034942626953125,-0.025604248046875,-0.044403076171875,-0.037750244140625,0.0374755859375,-0.01090240478515625,0.039947509765625,0.066162109375,0.0037479400634765625,0.020965576171875,-0.01107025146484375,0.0189361572265625,0.0216522216796875,-0.00666046142578125,0.0263214111328125,0.020263671875,-0.0013484954833984375,0.021026611328125,-0.0255279541015625,-0.05291748046875,-0.01195526123046875,0.041900634765625,-0.01312255859375,-0.0198211669921875,-0.01230621337890625,-0.002391815185546875,-0.043304443359375,-0.053253173828125,-0.01495361328125,0.0074310302734375,0.010