INSERT INTO city_chunks VALUES(88,'portland',10,'o identify barriers to housing and connect residents to medical and social resources - NOTE: Provides an affirming environment for LGBTQIA2S+ people who may not feel safe or welcome in other shelters. ### RESOURCE: Weidler Village - Type: alternative_shelter_village - Population: primarily Black, Indigenous, and people of color (BIPOC) - Access: referral-based - Features: - Culturally specific environment where most participants and staff identify as BIPOC - Tiny homes with meals, hygiene, laundry, storage, Wi‑Fi, transit access - Service planning and connections to medical and housing resources - NOTE: Designed to address racial inequities and provide a culturally responsive shelter environment. ### RESOURCE: N Portland Road (10505 N Portland Road) - Type: alternative_shelter_village_with_RV_parking - Population: adults 18+; includes people living in vehicles - Access: referrals from outreach workers; no waitlist - Features: - Tiny home units plus designated RV parking spaces - Pets allowed; couples can stay together; no outside guests - Transitional housing with no strict time limit - Meals, ADA-accessible showers and restrooms, laundry, storage, electricity, Wi‑Fi, transit access - Case management and service planning - NOTE: RV parking is especially important in Portland, where a significant share of unsheltered residents live in vehicles after being priced out of housing.','[0.0081329345703125,-0.020599365234375,-0.0038585662841796875,0.0016965866088867188,0.06805419921875,0.06060791015625,0.04620361328125,0.01219940185546875,-0.0243377685546875,-0.04425048828125,-0.01873779296875,-0.052734375,-0.029541015625,0.0263519287109375,-0.035430908203125,0.0528564453125,0.08251953125,-0.002811431884765625,0.006988525390625,-0.00008279085159301758,0.027008056640625,-0.007099151611328125,0.021392822265625,0.0458984375,0.01043701171875,0.01629638671875,0.05975341796875,-0.043060302734375,-0.05816650390625,-0.042388916015625