INSERT INTO city_chunks VALUES(89,'portland',11,'ss - Case management and service planning - NOTE: RV parking is especially important in Portland, where a significant share of unsheltered residents live in vehicles after being priced out of housing. The site allows them to remain in their vehicle while accessing services and work. ## RESOURCE TYPE: Congregate and emergency shelters ### RESOURCE: Burnside Shelter (SAFES) – 30 SW 2nd Ave - Type: emergency_overnight_shelter - Population: women-identifying adults (18+) - Access: first-come, first-served; nightly check-in around 7pm - Features: - Emergency overnight beds only; guests must leave during the day - Pets allowed - No ID or sobriety requirement, but substances are not allowed on the property - Operator: Salvation Army (faith-based Christian organization) ### RESOURCE: Moore Street Shelter - Type: emergency_overnight_shelter - Population: mixed-gender adults (18+) - Access: first-come, first-served; nightly check-in around 7pm - Features: - Emergency overnight beds only; guests must leave during the day - Pets allowed - No ID or sobriety requirement, but substances are not allowed on the property - Operator: Salvation Army (faith-based Christian organization)','[0.00811004638671875,0.00785064697265625,0.0234527587890625,0.0176544189453125,0.052490234375,0.0002579689025878906,0.08349609375,0.02423095703125,-0.032806396484375,-0.034576416015625,-0.011810302734375,0.0021915435791015625,-0.0582275390625,0.00452423095703125,-0.0164337158203125,0.04840087890625,0.0770263671875,-0.0186004638671875,-0.01050567626953125,-0.005390167236328125,0.03753662109375,0.00799560546875,0.01117706298828125,0.0243377685546875,0.042083740234375,0.009674072265625,0.0188446044921875,-0.0100250244140625,-0.0560302734375,-0.0156707763671875,0.0291748046875,-0.00894927978515625,-0.0102081298828125,0.0039825439453125,0.036041259765625,-0.020599365234375,0.0081024169921875,-0.024658203125,-0.00894927978515625,0.0242919921875,-0.019683837890